# misspellings / spelling variants -> one spelling (applied to whole upper-case words or phrases, in this order)
FIX = [
    (r'COTTON SEEDS? OIL', 'COTTONSEED OIL'), (r'\bPIEGON\b', 'PIGEON'), (r'\bTAMATRIND\b', 'TAMARIND'), (r'\bCOCNUT\b', 'COCONUT'),
    (r'\bSPILT\b', 'SPLIT'), (r'\bCHICK PEAS?\b', 'CHICKPEAS'), (r'\bCORAINDER(S?)\b', r'CORIANDER\1'),
    (r'\bPASTERUZIED\b|\bPASTURIZED\b|\bPASTEURIZED\b', 'PASTEURISED'), (r'\bIODIESD\b|\bIODIZED\b|\bLODISED\b', 'IODISED'),
    (r'\bSLAT\b', 'SALT'), (r'\bGRREN\b', 'GREEN'), (r'\bCAPISICUM\b', 'CAPSICUM'), (r'\bHYDROLYZED?\b|\bHYDROLYSE\b|\bHYDROLYZE\b', 'HYDROLYSED'),
    (r'\bPROTIEN\b', 'PROTEIN'), (r'\bPUROPSES\b', 'PURPOSE'), (r'ALL PURPOSE', 'ALL-PURPOSE'), (r'\bASAEFOETIDA\b', 'ASAFOETIDA'),
    (r'\bCINNAMOM\b', 'CINNAMON'), (r'\bCHILLY\b', 'CHILLI'), (r'\bSOYABEAN\b', 'SOYBEAN'), (r'VEG\.FAT', 'VEGETABLE FAT'),
    (r'\bMANGOPULP\b', 'MANGO PULP'), (r'\bSOYA SAUCE\b', 'SOY SAUCE'), (r'\bGREENCHILLI\b', 'GREEN CHILLI'), (r'\bCURRY LEAVE S\b', 'CURRY LEAVES'),
    (r'\bSPICE & CONDIMENTS\b', 'SPICES & CONDIMENTS'),
    (r'\bRICE,PIGEON\b', 'RICE, PIGEON'),
    # two missing commas
    (r'CLARIFIED BUTTER GRAM FLOUR', 'CLARIFIED BUTTER, GRAM FLOUR'), (r'CLARIFIED BUTTER CURD', 'CLARIFIED BUTTER, CURD'),
    (r'HYDROLYSED VEGETABLE PROTEIN \(SOYA\) VEGETABLE FAT', 'HYDROLYSED VEGETABLE PROTEIN (SOYA), VEGETABLE FAT'),
]
PROPER = ['French', 'Kesar', 'Kashmiri', 'Kabuli', 'Indian', 'Bengal', 'Kasuri', 'Kitchen King', 'Pav Bhaji', 'Sambar', 'Idli']
LOWER_AFTER = [(' And ', ' and ')]


def clean(raw, hits):
    s = re.sub(r'\s+', ' ', raw.strip()).rstrip('.').strip()
    for pat, rep in FIX:
        for m in re.finditer(pat, s):
            if m.group(0) != re.sub(pat, rep, m.group(0)):
                hits[m.group(0).lower() + '  ->  ' + re.sub(pat, rep, m.group(0)).lower()] += 1
        s = re.sub(pat, rep, s)
    s = re.sub(r'\s*,\s*', ', ', s)                      # one comma style
    s = re.sub(r'\(\s+', '(', s)
    s = re.sub(r'\s+\)', ')', s)
    s = re.sub(r'(\w)\(', r'\1 (', s)                    # GOOSEBERRY(AMLA) -> GOOSEBERRY (AMLA)
    s = s.lower()
    s = s[0].upper() + s[1:]
    for w in PROPER:
        s = re.sub(r'\b' + w.lower() + r'\b', w, s)
    return s


def main():
    hits = Counter()
    out = {}
    for pid, v in RAW.items():
        if isinstance(v, list):
            out[pid] = [[label, clean(t, hits)] for label, t in v]
        else:
            out[pid] = clean(v, hits)
    body = json.dumps(out, ensure_ascii=False, indent=1)
    (ROOT / 'product-ingredients.js').write_text(
        '/* product-ingredients.js: GENERATED by tools/build-ingredients.py from the client\'s ingredient lists. Do not edit by hand.\n'
        '   Key = product id. A string is one list; [[label, list], ...] is a product made of parts (Idli Sambar).\n'
        '   Combos are not listed here: pdp/ingredients.js shows the lists of their pouches. */\n'
        'window.PRODUCT_INGREDIENTS = ' + body + ';\n', encoding='utf-8')
    print('written:', len(out), 'products')
    print('spelling fixes (%d kinds, %d times):' % (len(hits), sum(hits.values())))
    for k, n in sorted(hits.items()):
        print('  %-55s x%d' % (k, n))


if __name__ == '__main__':
    main()
